const iconRegistry = { LayoutDashboard, ClipboardList, ChartNoAxesCombined, CalendarDays, FlaskConical, Info, ArrowUpRight, ArrowRight, ArrowLeft, ChevronRight, Check, CheckCheck, ShieldCheck, Clock3, BookOpen, Code2, FolderGit2, MessagesSquare, FileUser, ListChecks, Target, Sparkles, TrendingUp, Download, Upload, Menu, X, LockKeyhole, CircleHelp, CircleCheck, Trash2, RotateCcw, ExternalLink, Lightbulb, Route, Leaf, CircleAlert, Save, ChevronDown };
const icon = name => `<i data-lucide="${name}" aria-hidden="true"></i>`;
