function planPage() {
  const r = currentResult();
  return heading('Make your next week count','Your seven-day starter plan','Specific practice. Manageable sessions. A clear way to know when you’re done.') + (r ? planContent(r) : empty('Your plan begins with your priorities.','Complete a readiness assessment to get a plan based on your actual inputs. Nothing here is a generic pre-filled student record.'));
}
function progressPage() {
  if (!records.length) return heading('Your effort, over time','My progress','A record of the assessments you chose to save. Compare your own preparation—not other students.') + empty('Your starting line is waiting.','Complete an assessment and choose Save assessment. Your genuine history, trends and category changes will appear here.');
  const last = records.at(-1), previous=records.at(-2), delta = previous?last.score-previous.score:0;
  return `${heading('Your effort, over time','Look at how far you’ve come.','A record of your saved assessments. New evidence matters more than a higher self-rating.',`<div class="button-row">${button(`${icon('download')} Export CSV`,'export-history','small')}${link(`${icon('clipboard-list')} Reassess`,'/assessment','primary small')}</div>`)}<div class="metrics"><div class="metric"><div class="metric-label">Latest readiness score</div><div class="metric-value">${fmt(last.score)}<small> / 100</small></div><div class="metric-note">${previous?`${delta>=0?'+':''}${fmt(delta)} from previous`:'Your first honest baseline'}</div></div><div class="metric"><div class="metric-label">First assessment</div><div class="metric-value">${fmt(records[0].score)}<small> / 100</small></div><div class="metric-note">${dateText(records[0].created_at)}</div></div><div class="metric"><div class="metric-label">Saved assessments</div><div class="metric-value">${records.length}</div><div class="metric-note">On this browser only</div></div></div>${previous?`<div class="progress-columns"><section class="panel"><h3>Your readiness trend</h3><p>Score out of 100, in assessment order.</p><div class="chart-wrap"><canvas id="trend-chart" role="img" aria-label="Readiness scores in assessment order: ${records.map(r=>fmt(r.score)).join(', ')}"></canvas></div></section><section class="panel"><h3>What changed since last time?</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Category</th><th>Latest</th><th>Change</th></tr></thead><tbody>${CATEGORY_NAMES.map((name,i)=>{const diff=last.categories[name]-previous.categories[name];return `<tr><td>${categoriesShort[i]}</td><td>${fmt(last.categories[name])}</td><td class="delta ${diff>=0?'positive':'negative'}">${diff>=0?'+':''}${fmt(diff)}</td></tr>`;}).join('')}</tbody></table></div></section></div>${JSON.stringify(last.missing_optional)!==JSON.stringify(previous.missing_optional)||last.scoring_version!==previous.scoring_version?`<div class="notice warning">${icon('circle-alert')}Optional-test coverage or scoring version changed. These scores are not a like-for-like measure of improvement.</div>`:''}`:`<div class="notice">${icon('trending-up')}One baseline saved. Save another assessment after practicing to see a trend and category changes.</div>`}<section class="panel"><div class="section-heading"><h3>Assessment history</h3><small>Newest first · local time</small></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Score</th><th>Readiness band</th><th>Optional tests missing</th><th></th></tr></thead><tbody>${[...records].reverse().map(r=>`<tr><td>${dateText(r.created_at)}<br><small>${new Date(r.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small></td><td><strong>${fmt(r.score)}</strong> / 100</td><td>${esc(r.band)}</td><td>${r.missing_optional.length}</td><td>${button('View result','view-record','small',`data-id="${esc(r.id)}"`)}</td></tr>`).join('')}</tbody></table></div></section><div class="subtle-note">${icon('lock-keyhole')}<span>Your records live in this browser, not on Vercel’s temporary disk. Export a backup before changing devices or clearing browser data. <a href="/privacy" data-nav>Manage privacy & backups.</a></span></div>`;
}
function modelPage() {
  if (!metadata) return heading('Behind the numbers','Model insights','An educational machine-learning workflow, deliberately separate from your readiness score.') + `<div class="error-state"><p>Model insights could not be loaded. Your readiness assessment still works.</p>${button('Retry model insights','retry-model','')}</div>`;
  const meta=metadata;
  return `${heading('The learning lab','Understand the model. Know its limits.','A reproducible machine-learning demonstration—not a forecast of your placement outcome.')}<div class="notice warning">${icon('flask-conical')}<span><strong>Synthetic data only.</strong> These are simulated interview-exercise outcomes, not real students or genuine placements. These metrics do not establish real-world accuracy.</span></div><div class="tabs" role="tablist" aria-label="Model insights"><button role="tab" aria-selected="${modelTab==='evaluation'}" data-action="model-tab" data-tab="evaluation" class="${modelTab==='evaluation'?'active':''}">Evaluation</button><button role="tab" aria-selected="${modelTab==='data'}" data-action="model-tab" data-tab="data" class="${modelTab==='data'?'active':''}">Data & workflow</button><button role="tab" aria-selected="${modelTab==='inference'}" data-action="model-tab" data-tab="inference" class="${modelTab==='inference'?'active':''}">Try the model</button></div><div role="tabpanel">${modelTab==='evaluation'?modelEvaluation(meta):modelTab==='data'?modelData(meta):modelInference()}</div><div class="prose"><h2>Limitations to keep in view</h2><ul>${meta.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul></div>`;
}
function modelEvaluation(meta) {
  return `<div class="metrics"><div class="metric"><div class="metric-label">Simulated observations</div><div class="metric-value">${meta.audit.usable_observations.toLocaleString()}</div></div><div class="metric"><div class="metric-label">Train / held-out test</div><div class="metric-value">${meta.training_rows} <small>/ ${meta.test_rows}</small></div></div><div class="metric"><div class="metric-label">Fixed random seed</div><div class="metric-value">${meta.seed}</div></div></div><section class="panel"><div class="section-heading"><h3>Model comparison</h3><small>Five-fold stratified CV · training rows only</small></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Candidate</th><th>CV F1 mean</th><th>Standard deviation</th></tr></thead><tbody>${meta.comparison.map(row=>`<tr><td>${row.model===meta.model_name?'<strong>':''}${esc(row.model)}${row.model===meta.model_name?' · selected</strong>':''}</td><td>${row.cv_f1_mean.toFixed(4)}</td><td>${row.cv_f1_std.toFixed(4)}</td></tr>`).join('')}</tbody></table></div><p>Selected by highest mean CV F1. The untouched held-out partition did not select the winner.</p></section><div class="section-heading" style="margin-top:30px"><h2>Selected model · held-out synthetic test</h2></div><div class="model-metrics">${['accuracy','precision','recall','f1'].map(k=>`<div class="metric"><div class="metric-label">${k==='f1'?'F1-score':k[0].toUpperCase()+k.slice(1)}</div><div class="metric-value">${meta.test_metrics[k].toFixed(3)}</div></div>`).join('')}</div><div class="two-columns"><section class="panel"><h3>Confusion matrix</h3><p>Rows = actual · columns = predicted</p><table class="confusion-table"><caption class="visually-hidden">Synthetic holdout confusion matrix</caption><thead><tr><th scope="col">Actual / predicted</th><th scope="col">Predicted fail</th><th scope="col">Predicted pass</th></tr></thead><tbody><tr><th scope="row">Actual fail</th><td class="high">${meta.test_metrics.confusion_matrix[0][0]}</td><td>${meta.test_metrics.confusion_matrix[0][1]}</td></tr><tr><th scope="row">Actual pass</th><td>${meta.test_metrics.confusion_matrix[1][0]}</td><td class="high">${meta.test_metrics.confusion_matrix[1][1]}</td></tr></tbody></table></section><section class="panel"><h3>Class distribution</h3><p>Full simulated dataset · ${meta.audit.class_distribution['0']} fail / ${meta.audit.class_distribution['1']} pass</p><div class="chart-wrap short"><canvas id="class-chart" role="img" aria-label="${meta.audit.class_distribution['0']} simulated failures and ${meta.audit.class_distribution['1']} simulated passes"></canvas></div></section></div><div class="prose"><p style="margin-top:22px"><strong>Accuracy:</strong> fraction correct. <strong>Precision:</strong> fraction of predicted simulated passes that pass. <strong>Recall:</strong> fraction of simulated passes detected. <strong>F1:</strong> balances precision and recall.</p><p style="margin-top:12px">A false positive predicts a simulated pass for a failure; a false negative misses a simulated pass. Neither should be interpreted as a real hiring decision.</p><h2>Permutation importance</h2><p>Mean F1 drop after shuffling a feature on the holdout. Negative values can occur. Eight shuffles per feature; standard deviation is shown numerically. Correlation can share importance—importance is not causation.</p></div><div class="table-wrap" style="margin-top:18px"><table class="data-table"><thead><tr><th>Feature</th><th>Mean F1 drop</th><th>Standard deviation</th></tr></thead><tbody>${[...meta.permutation_importance].sort((a,b)=>b.mean-a.mean).map(row=>`<tr><td>${esc(row.feature)}</td><td>${row.mean.toFixed(4)}</td><td>${row.std.toFixed(4)}</td></tr>`).join('')}</tbody></table></div><p class="current-note">Trained ${dateText(meta.trained_at_utc)} · Scikit-learn ${esc(meta.sklearn_version)} · Artifacts loaded, never retrained on interaction.</p>`;
}
function modelData(meta) {
  return `<div class="prose"><h2>Where this data comes from</h2><p>${esc(meta.dataset)} No verified real-world placement dataset was available in the original repository, so this project uses an explicitly synthetic fallback.</p><p style="margin-top:12px"><strong>Target:</strong> ${esc(meta.target_definition)}</p><h2>The generation recipe</h2><p>A shared normal latent preparation variable produces correlated CGPA, ratings and aptitude. Coding practice uses a capped gamma distribution. Internship is sampled separately. A documented logistic relationship combines these features; labels are sampled from a Bernoulli distribution, so they are related but intentionally noisy. About 3.5% missingness is introduced in aptitude and communication after labels are generated.</p><h2>A leakage-safe workflow</h2><ol><li>Validate schema, ranges and binary labels; remove duplicate predictor rows.</li><li>Hold out 20% of rows, stratified, with seed 42.</li><li>Fit median imputation, numerical scaling and categorical encoding inside each training fold.</li><li>Compare Logistic Regression, a constrained Decision Tree and Random Forest with five-fold F1.</li><li>Refit the winner on all training rows and evaluate once on the untouched holdout.</li><li>Save the trusted pipeline, schema, checksum, dependency version and measured metadata.</li></ol><p>No salary, final hiring status or other future information is used as a predictor. A real dataset requires provenance, permissions, leakage review, external validation and bias analysis before any outcome claim.</p><h2>Data audit</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Feature</th><th>Missing observations</th></tr></thead><tbody>${Object.entries(meta.audit.missing_values).map(([key,value])=>`<tr><td>${esc(key)}</td><td>${value}</td></tr>`).join('')}</tbody></table></div><p class="current-note">${meta.audit.duplicate_feature_rows_removed} duplicate predictor rows removed. The detailed generation formula and licensing notes are in data/README.md.</p><div class="prose"><h2>Reproduce locally</h2></div><pre class="code">python -m src.train_model --generate</pre>`;
}
function modelInference() {
  const fields = [['cgpa','CGPA',0,10,7,.1],['coding_practice','Coding problems understood',0,500,80,1],['dsa_rating','DSA self-rating',1,5,3,1],['project_quality','Project quality rating',1,5,3,1],['aptitude','Aptitude percentage',0,100,60,1],['communication','Communication rating',1,5,3,1]];
  return `<div class="prose"><h2>Exercise the saved pipeline</h2><p>Use an illustrative row to see inference work. The result is a simulated exercise class—not your readiness score or an employment forecast. It is never saved to assessment history.</p></div><form id="simulation-form" class="model-form"><div class="form-fields">${fields.map(([key,label,min,max,value,step])=>`<div class="field"><label for="sim-${key}">${label}</label><input type="number" id="sim-${key}" name="${key}" min="${min}" max="${max}" value="${value}" step="${step}" required></div>`).join('')}<div class="field"><label for="sim-internship">Internship</label><select name="internship" id="sim-internship"><option value="none">No experience</option><option value="completed">Completed</option></select></div></div><div id="form-error" aria-live="polite"></div><button type="submit" class="btn primary" style="margin-top:25px">Run simulated inference ${icon('arrow-right')}</button><div id="simulation-result" aria-live="polite"></div></form>`;
}
function aboutPage() {
  return `${heading('Useful by design. Honest by default.','A little clarity for every student.','Path2Placement helps engineering students decide what to work on next, without pretending to know their future.')}<div class="about-columns"><div class="prose"><h2 style="margin-top:0">The question we’re answering</h2><p>“What should I improve before applying?” is more useful than an unsupported placement probability. This project turns five preparation areas into a repeatable snapshot, specific practice tasks and genuine personal progress.</p><h2>Two systems. A clear boundary.</h2><p><strong>Readiness assessment:</strong> a deterministic, versioned scoring formula. No trained model or external LLM calculates your score or recommendations.</p><p style="margin-top:12px"><strong>ML learning lab:</strong> three classifiers trained on explicitly simulated exercise outcomes. It demonstrates preprocessing, evaluation and inference—not actual placement forecasting.</p></div><aside class="panel soft"><div class="eyebrow">Simple tools. Clear boundaries.</div><h2>Built to be understood.</h2><ul class="check-list"><li>${icon('check')} No student rankings or invented success stories.</li><li>${icon('check')} No paid AI API or external LLM.</li><li>${icon('check')} No account or sensitive personal data required.</li><li>${icon('check')} Open, documented scoring criteria.</li></ul><div class="stack-list"><span>Python</span><span>Flask</span><span>Vanilla JS</span><span>Vite</span><span>Scikit-learn</span><span>Chart.js</span></div></aside></div><div class="prose"><h2>Every point, explained.</h2><p>Scoring version ${esc(config.scoring_version)}. All input values are normalized to 0–100. The five category weights sum to 100%. Missing optional tests are excluded and the remaining inputs are reweighted within that category only.</p></div><section style="margin-top:15px">${config.categories.map(cat=>`<details class="disclosure"><summary>${cat.name} · ${Math.round(cat.weight*100)}% of overall score</summary><div><div class="table-wrap"><table class="data-table"><thead><tr><th>Input</th><th>Within category</th><th>Normalization</th></tr></thead><tbody>${Object.entries(cat.fields).map(([key,weight])=>{const f=config.fields[key]; return `<tr><td>${esc(f.label)}</td><td>${Math.round(weight*100)}%</td><td>${f.cap?`min(value / ${f.cap}, 1) × 100`:`(value − ${f.minimum}) / ${f.maximum-f.minimum} × 100`}</td></tr>`;}).join('')}</tbody></table></div></div></details>`).join('')}</section><div class="prose"><h2>Readiness bands are design choices.</h2><p>0–&lt;40: Foundation Building · 40–&lt;60: Developing · 60–&lt;75: Progressing Toward Readiness · 75–&lt;90: Nearly Ready · 90–100: Strong Preparation.</p><p style="margin-top:12px">Bands use the exact two-decimal score, not the rounded headline. These boundaries are not scientifically validated measures of employability.</p><h2>Responsible use comes first.</h2><p>Self-ratings are subjective. Access to internships, equipment and mentoring is unequal. Our criteria do not capture every skill, opportunity or circumstance. Your score is not your worth, and it should never be used for hiring, admission, student ranking or other high-stakes decisions.</p><h2>What comes next?</h2><p>Validated skill quizzes, student usability feedback, configurable career tracks and—only with proper permissions—a representative real dataset with external and subgroup evaluation. Optional account-based synchronization would require a separate privacy and security design.</p></div><div class="subtle-note">${icon('lock-keyhole')}<span>This web version keeps explicitly saved history in your browser. The original local Streamlit application remains available in this repository. <a href="/privacy" data-nav>Read the storage details.</a></span></div>`;
}
function privacyPage() {
  return `${heading('Your preparation. Your data.','Privacy & browser history','Understand exactly what is saved, where it lives, and how to keep or remove it.')}<div class="about-columns"><div class="prose"><h2 style="margin-top:0">No account. No shared student database.</h2><p>When you calculate, your answers are sent securely to the Python API for validation and scoring. The app does not write those inputs or results to a server database and does not log request bodies.</p><p style="margin-top:12px">Only after you choose <strong>Save assessment</strong> does this website store inputs, scores, recommendations, the seven-day plan and timestamps in <strong>this browser’s local storage</strong>. Drafts and unsaved results live in this tab’s session storage. Completion ticks stay in local storage.</p><h2>This is device-local, not account-private.</h2><p>Someone using the same browser profile on a shared device can open this history. There is no login or encryption at rest. Use a private device, export what matters and clear history when finished. Private-browsing sessions and browser cleanup may erase it.</p><h2>Switching devices?</h2><p>Download a JSON backup and restore it in your other browser. CSV is a readable report, not a restorable backup. Restoring a backup sends its input values through the API to recompute scores under the current criteria; saved recommendations and scores are never blindly trusted.</p><p style="margin-top:12px">No email addresses, names, passwords, demographic attributes or sensitive identifiers are needed. Vercel, as the host, processes normal request metadata under its own policies. This is an educational prototype, not an enterprise identity or confidential-records system.</p></div><aside><section class="panel privacy-section"><h3>Your saved data</h3><p><strong>${records.length}</strong> assessment${records.length===1?'':'s'} saved in this browser.</p><div class="data-actions">${button(`${icon('download')} Export CSV`,'export-history','small',!records.length?'disabled':'')}${button(`${icon('download')} JSON backup`,'backup-history','small',!records.length?'disabled':'')}</div><label class="btn small" for="restore-file">${icon('upload')} Restore a JSON backup</label><input class="display-none" type="file" id="restore-file" accept="application/json,.json"><p class="current-note">Backups contain your assessment inputs. Keep them private. Maximum 200 records per browser.</p><div id="restore-status" role="status" aria-live="polite"></div></section><section class="panel privacy-section"><h3>Start with a clean slate</h3><p>Delete saved assessments, plan ticks, and this tab’s draft and result. Download a backup first if you want to keep them.</p><label class="delete-confirm"><input type="checkbox" id="confirm-delete"> I understand this cannot be undone.</label><button class="btn danger small" style="margin-top:16px" id="delete-history" data-action="delete-history" disabled>${icon('trash-2')} Delete my browser data</button></section></aside></div>`;
}
function chartOptions(max=100) { return {responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{backgroundColor:'#294e36',padding:10}},scales:{x:{grid:{display:false},border:{display:false},ticks:{color:'#5b6854',font:{size:10},maxTicksLimit:8}},y:{min:0,max,border:{display:false},grid:{color:'#e8eddf'},ticks:{color:'#5b6854',font:{size:10},stepSize:max===100?25:undefined}}},animation:false}; }
function mountCharts() {
  const trend=document.querySelector('#trend-chart');
  if (trend) charts.push(new Chart(trend,{type:'line',data:{labels:records.map((_,i)=>`#${i+1}`),datasets:[{data:records.map(r=>r.score),borderColor:'#245c48',backgroundColor:'#245c480c',fill:true,pointBackgroundColor:'#fff',pointBorderColor:'#245c48',pointBorderWidth:2,pointRadius:4,borderWidth:2,tension:.15}]},options:chartOptions()}));
  const dist=document.querySelector('#class-chart');
  if(dist) charts.push(new Chart(dist,{type:'bar',data:{labels:['Simulated fail','Simulated pass'],datasets:[{data:[metadata.audit.class_distribution['0'],metadata.audit.class_distribution['1']],backgroundColor:['#9aad8d','#245c48'],borderRadius:2,maxBarThickness:85}]},options:chartOptions(Math.ceil(Math.max(...Object.values(metadata.audit.class_distribution))/100)*100)}));
}
function render() {
  destroyCharts();
  const routes = {'/':overview,'/assessment':assessment,'/results':resultPage,'/progress':progressPage,'/plan':planPage,'/model':modelPage,'/about':aboutPage,'/privacy':privacyPage};
  const page=routes[location.pathname];
  app.innerHTML=shell(page?page():heading('A small detour','This page isn’t here.','Use the navigation to get back to your preparation.')+link('Back to overview','/','primary'));
  document.title=`${[...navItems,...extraNav,['/privacy','Privacy & data']].find(n=>n[0]===location.pathname)?.[1]||'Path2Placement'} · Path2Placement`;
  icons(); mountCharts();
}
function collectDraft(form) {
  for(const [key,value] of new FormData(form)) if(config.fields[key]) draft[key]=value===''?null:Number(value);
  persistSession();
}
async function calculate(buttonEl) {
  buttonEl.disabled=true; buttonEl.textContent='Calculating your snapshot…';
  try {
    const response=await api('assess',draft);
    result={...response,id:crypto.randomUUID(),created_at:new Date().toISOString()};
    persistSession(); tab='actions';navigate('/results');
  } catch(e) { apiError(e.message); buttonEl.disabled=false;buttonEl.innerHTML=`Calculate my readiness ${icon('arrow-right')}`;icons(); }
}
function download(content,name,type) { const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }
async function restoreBackup(file) {
  const status=document.querySelector('#restore-status');
  if(!file) return;
  try {
    if(file.size>2_000_000)throw new Error('Use a backup smaller than 2 MB.');
    const imported=parseBackup(await file.text());
    const ids=new Set(records.map(r=>r.id)); const additions=imported.filter(r=>!ids.has(r.id));
    if(records.length+additions.length>MAX_RECORDS)throw new Error('Restoring this backup would exceed the 200-assessment limit.');
    status.textContent=`Checking ${additions.length} assessment(s)… Keep this page open.`;
    // Stage the full import before committing. Failed validation never partially writes history.
    const validated=[];
    for(const r of additions){ const response=await api('assess',r.inputs);validated.push({...response,id:r.id,created_at:r.created_at,restored:true}); }
    localStorage.setItem(HISTORY_KEY,JSON.stringify([...records,...validated]));
    refreshHistory();render();toast(`${validated.length} assessment(s) restored. Scores recomputed using the current criteria.`);
  } catch(e) {if(status.isConnected)status.textContent=e.message;else toast(e.message);}
}
app.addEventListener('click',async event=>{
  const nav=event.target.closest('a[data-nav]');
  if(nav && !event.metaKey && !event.ctrlKey && !event.shiftKey && event.button===0){event.preventDefault();navigate(nav.getAttribute('href'));return;}
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;
  const action=el.dataset.action;
  if(action==='toggle-menu'){mobileOpen=!mobileOpen;document.querySelector('.sidebar')?.classList.toggle('open',mobileOpen);document.querySelector('.backdrop')?.classList.toggle('open',mobileOpen);document.querySelector('.mobile-toggle')?.setAttribute('aria-expanded',String(mobileOpen));if(mobileOpen)document.querySelector('.sidebar a')?.focus();else document.querySelector('.mobile-toggle')?.focus();return;}
  if(action==='edit-step'||action==='back-step'){if(action==='edit-step')step=Number(el.dataset.step);else step=Math.max(0,step-1);persistSession();render();window.scrollTo(0,0);return;}
  if(action==='calculate')return calculate(el);
  if(action==='save-result'){
    const r=currentResult();
    try{records=saveAssessment(r);storageError='';render();toast('Assessment saved in this browser. Your next step is ready.');}catch(e){toast(e.message);}return;
  }
  if(action==='view-record'){result=records.find(r=>r.id===el.dataset.id);tab='actions';persistSession();navigate('/results');return;}
  if(action==='update-assessment'){draft={...currentResult().inputs};step=0;persistSession();navigate('/assessment');return;}
  if(action==='result-tab'){tab=el.dataset.tab;render();document.querySelector('.tabs')?.scrollIntoView({block:'nearest'});return;}
  if(action==='model-tab'){modelTab=el.dataset.tab;render();document.querySelector('.tabs')?.scrollIntoView({block:'nearest'});return;}
  if(action==='retry-model'){try{metadata=await api('model');render();}catch(e){toast(e.message);}return;}
  if(action==='export-history'){download(historyCsv(records),'path2placement-history.csv','text/csv;charset=utf-8');return;}
  if(action==='backup-history'){download(JSON.stringify({version:2,exported_at:new Date().toISOString(),assessments:records},null,2),'path2placement-backup.json','application/json');return;}
  if(action==='export-plan'){
    const r=currentResult(); const q=v=>`"${String(v).replaceAll('"','""')}"`;
    download([Object.keys(r.plan[0]),...r.plan.map(d=>Object.values(d))].map(row=>row.map(q).join(',')).join('\r\n'),'path2placement-seven-day-plan.csv','text/csv;charset=utf-8');return;
  }
  if(action==='delete-history'){
    if(!document.querySelector('#confirm-delete')?.checked)return;
    try{clearHistory();const keys=Object.keys(localStorage).filter(k=>k.startsWith('p2p.plan.'));keys.forEach(k=>localStorage.removeItem(k));sessionStorage.removeItem('p2p.draft');sessionStorage.removeItem('p2p.result');records=[];result=null;draft=Object.fromEntries(Object.entries(config.fields).map(([key,f])=>[key,f.default]));step=0;storageError='';render();toast('Your saved assessments and this tab’s draft have been deleted.');}catch{toast('Your browser did not allow deletion. Use browser site settings to clear this site’s storage.');}return;
  }
});
app.addEventListener('input',event=>{
  const form=event.target.closest('#assessment-form');if(form){collectDraft(form);if(event.target.type==='radio'){const k=event.target.name;const desc=document.querySelector('#descriptor-'+k);if(desc)desc.textContent=`${draft[k]} · ${ratingNames[draft[k]-1]}`;}}
});
app.addEventListener('change',event=>{
  if(event.target.id==='confirm-delete'){document.querySelector('#delete-history').disabled=!event.target.checked;return;}
  if(event.target.id==='restore-file')return restoreBackup(event.target.files[0]);
  if(event.target.dataset.planDay){const el=event.target;const id=el.dataset.id;const checks=new Set(planChecks(id));const day=Number(el.dataset.planDay);el.checked?checks.add(day):checks.delete(day);try{localStorage.setItem('p2p.plan.'+id,JSON.stringify([...checks]));const y=window.scrollY;render();window.scrollTo(0,y);}catch{toast('This browser could not save the checklist.');}return;}
  const form=event.target.closest('#assessment-form');if(form)collectDraft(form);
});
app.addEventListener('submit',async event=>{
  if(event.target.id==='assessment-form'){
    event.preventDefault();const form=event.target;collectDraft(form);const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Checking section…';
    try{await api('validate',{category:config.categories[step].name,inputs:draft});step++;persistSession();render();window.scrollTo(0,0);document.querySelector('.form-section h2,.page-heading h2')?.focus();}catch(e){apiError(e.message);submit.disabled=false;submit.innerHTML=`${step===4?'Review my answers':'Save & continue'} ${icon('arrow-right')}`;icons();}return;
  }
  if(event.target.id==='simulation-form'){
    event.preventDefault();const form=event.target;const data=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,k==='internship'?v:Number(v)]));const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Running the saved model…';
    try{const out=await api('simulate',data);document.querySelector('#simulation-result').innerHTML=`<div class="notice">${icon('flask-conical')}<span><strong>Simulated exercise class: ${out.simulated_class?'pass':'fail'}.</strong><br>${esc(out.explanation)}</span></div>`;icons();}catch(e){apiError(e.message);}finally{submit.disabled=false;submit.innerHTML=`Run simulated inference ${icon('arrow-right')}`;icons();}
  }
});
window.addEventListener('popstate',()=>{mobileOpen=false;render();});
window.addEventListener('storage',event=>{if(event.key===HISTORY_KEY){refreshHistory();render();}});
window.addEventListener('keydown', event => {
  const tablist = event.target.closest?.('[role=tablist]');
  if (tablist && ['ArrowLeft','ArrowRight','Home','End'].includes(event.key)) {
    event.preventDefault(); const tabs = [...tablist.querySelectorAll('[role=tab]')];
    let index = tabs.indexOf(event.target);
    index = event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;
    const key=tabs[index].dataset.tab; tabs[index].click();document.querySelector(`[role=tab][data-tab="${key}"]`)?.focus();
  }
  if (mobileOpen && event.key==='Tab') {
    const items=[...document.querySelectorAll('.sidebar a')];const first=items[0],last=items.at(-1);
    if(event.shiftKey && document.activeElement===first){event.preventDefault();last.focus();}
    else if(!event.shiftKey && document.activeElement===last){event.preventDefault();first.focus();}
  }
});
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobileOpen){mobileOpen=false;document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.backdrop')?.classList.remove('open');document.querySelector('.mobile-toggle')?.setAttribute('aria-expanded','false');document.querySelector('.mobile-toggle')?.focus();}});
async function boot(){
  app.innerHTML='<div class="loading" role="status"><span class="spinner"></span>Opening your preparation workspace…</div>';
  try{
    config=await api('config');refreshHistory();
    const saved=sessionRead('p2p.draft');
    draft=Object.fromEntries(Object.entries(config.fields).map(([key,f])=>[key,saved?.inputs?.[key]??f.default]));
    // Explicit nulls in optional fields must not turn into invented test scores.
    for(const [key,f] of Object.entries(config.fields))if(f.optional&&saved?.inputs&&key in saved.inputs)draft[key]=saved.inputs[key];
    step=Number.isInteger(saved?.step)&&saved.step>=0&&saved.step<=5?saved.step:0;
    const cached=sessionRead('p2p.result');
    result=isRecord(cached)?cached:null;
    try{metadata=await api('model');}catch{metadata=null;}
    render();
  }catch(e){app.innerHTML=`<main class="main"><div class="error-state"><div class="eyebrow">Let’s try that again</div><h1>Your workspace couldn’t open.</h1><p>${esc(e.message)}</p><button class="btn primary" id="retry-boot">Retry connection</button></div></main>`;document.querySelector('#retry-boot').onclick=boot;}
}
boot();
